 gate('MULTIFREQUENCY_DYNAMIC_TRAJECTORIES_COMPLETED','PASS' if any(r['status']=='PASS' and r['task']['frequency']!=2500000. for r in long) else 'FAIL',['../f10ad_multifrequency/LONG.json'])
 gate('FREQUENCY_DEPENDENT_SHAPE_MODES_IDENTIFIED','PASS' if it['new_vs_historical_sign_categories'] else 'INCONCLUSIVE',['INTERPRETATION.json'],reason='New verified sign categories are narrower than new physical mechanisms')
 for name,ev in [('SHELL_PARAMETER_SENSITIVITY_EVALUATED','../f10ad_multifrequency/ROBUSTNESS.json'),('GPU_CPU_RESOURCES_RECORDED','COMPUTE_COST.json')]:gate(name,'PASS',[ev])
 gate('FULL_TRAJECTORY_DATASET_VALIDATED','PASS' if au['all_completed_independent_pass'] else 'FAIL',['AUDIT.json'],reason='Full-window admission applies only to complete trajectories; failures retained')
 for name,ev in [('FIGURES_VALIDATED','figures/MANIFEST.json'),('VIDEOS_VALIDATED','videos/MANIFEST.json')]:gate(name,'PASS' if (BASE/ev).exists() and (BASE/'evidence/media_review/AUTOMATED.json').exists() and (BASE/'evidence/media_review/MANUAL.json').exists() else 'NOT_RUN',[ev,'evidence/media_review/AUTOMATED.json','evidence/media_review/MANUAL.json'])
 for name in ['PHYSICS_CALIBRATED','ELECTRICAL_TO_ACOUSTIC_CALIBRATED','REAL_PDMS_FIELD_VALIDATED','REAL_PZT_CONTROL_VALIDATED','WORLD_MODEL_TRAINED']:gate(name,'NOT_RUN',['MODEL_LIMITATIONS.md'],reason='Outside this computational study')
 gate('TRAINING_READY','FAIL',['MODEL_LIMITATIONS.md'],reason='Uncalibrated physics; no ML readiness admission')
